const item = $input.first();
const incoming = item.json || {};
const body = incoming.body && typeof incoming.body === 'object' ? incoming.body : {};
const headers = incoming.headers && typeof incoming.headers === 'object' ? incoming.headers : {};
const suppliedKey = headers['x-excel-mas-key'] ?? headers['X-Excel-MAS-Key'] ?? '';
const expectedKey = typeof incoming.excel_mas_webhook_api_key === 'string' ? incoming.excel_mas_webhook_api_key : '';
const parseObject = (raw, fallback = {}) => {
  if (raw === undefined || raw === null || raw === '') return fallback;
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) return raw;
  if (typeof raw !== 'string') return fallback;
  const text = raw.trim();
  if (!text) return fallback;
  try {
    const parsed = JSON.parse(text);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : fallback;
  } catch { return { prompt: text }; }
};
const request = parseObject(incoming.request ?? body.request ?? body.payload ?? body, {});
const response = parseObject(incoming.clarification_response ?? body.clarification_response, null);
const sessionId = typeof (incoming.session_id ?? body.session_id) === 'string'
  ? (incoming.session_id ?? body.session_id).trim() : '';
const hasFile = Boolean(item.binary?.file);
return [{ json: {
  request,
  session_id: sessionId || undefined,
  clarification_response: response,
  entrypoint: 'mas_orchestrator',
  has_file: hasFile,
  mas_webhook_authorized: Boolean(expectedKey) && suppliedKey === expectedKey,
}, binary: item.binary }];

const coreResult = $input.first().json || {};
const sessionId = String(coreResult.meta?.session_id || coreResult.session_id || '').trim();
const status = String(coreResult.status || 'error');
const clarification = coreResult.clarification && typeof coreResult.clarification === 'object' ? coreResult.clarification : null;
const instruction = status === 'clarification_needed'
  ? 'The Excel Extractor specialist requires user input. Ask the user the exact clarification question(s) from clarification.questions. Preserve the session_id and clarification token verbatim. Do not answer or guess on the user’s behalf.'
  : status === 'success' || status === 'partial'
    ? 'The Excel Extractor specialist completed the request. State the result factually, including the row count and any warnings. Do not invent rows, columns, filters, artifacts, or a download link.'
    : 'The Excel Extractor specialist could not complete the request. Explain only the structured error and a safe next step. Do not speculate.';
return [{ json: {
  core_result: coreResult,
  session_id: sessionId || 'orchestrator-no-session',
  agent_input: JSON.stringify({ role: 'Excel MAS orchestrator', instruction, core_result: coreResult }),
} }];

const agent = $input.first().json || {};
const prepared = $('Prepare orchestrator handoff').first().json || {};
const core = prepared.core_result && typeof prepared.core_result === 'object' ? prepared.core_result : {};
const fallback = core.status === 'clarification_needed'
  ? 'Нужны уточнения по данным. Верните тот же session_id и ответы на все вопросы.'
  : core.status === 'success' || core.status === 'partial'
    ? `Extractor завершил обработку: ${core.data?.row_count ?? 0} строк(и).`
    : 'Extractor вернул ошибку; проверьте структурированный ответ.';
const candidate = agent.output ?? agent.text ?? agent.response ?? agent.message?.content;
const message = typeof candidate === 'string' && candidate.trim() ? candidate.trim().slice(0, 4000) : fallback;
return [{ json: {
  ...core,
  meta: { ...(core.meta || {}), entrypoint: 'mas_orchestrator', delegated_to: 'excel_extractor_core' },
  orchestrator: { message, session_id: core.meta?.session_id || core.session_id || null },
} }];
